package com.tradinggate.app;import android.accessibilityservice.AccessibilityService;import android.content.*;import android.view.accessibility.AccessibilityEvent;
public class TradingGateAccessibilityService extends AccessibilityService{static final String MT5="net.metaquotes.metatrader5";public void onAccessibilityEvent(AccessibilityEvent e){if(e==null||e.getPackageName()==null||!MT5.contentEquals(e.getPackageName()))return;SharedPreferences p=getSharedPreferences("gate",0);if(!p.getBoolean("unlocked",false)||p.getLong("until",0)<=System.currentTimeMillis()){p.edit().putBoolean("unlocked",false).apply();Intent i=new Intent(this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(i);}}public void onInterrupt(){}}
